    """
    Leitura incremental de um JSON cujo nível superior é uma lista.
    Evita carregar a wallet inteira na memória.
    """
    decoder = json.JSONDecoder()

    with open(path, "r", encoding="utf-8") as arquivo:
        buffer = ""
        iniciou_lista = False
        fim_arquivo = False

        while True:
            if not fim_arquivo and len(buffer) &lt; chunk_size:
                trecho = arquivo.read(chunk_size)
                if trecho:
                    buffer += trecho
                else:
                    fim_arquivo = True

            buffer = buffer.lstrip()

            if not iniciou_lista:
                if not buffer:
                    if fim_arquivo:
                        return
                    continue

                if buffer[0] != "[":
                    raise ValueError(
                        "O JSON de nível superior deve ser uma lista."
                    )

                buffer = buffer[1:]
                iniciou_lista = True
                continue

            if buffer.startswith(","):
                buffer = buffer[1:].lstrip()

            if buffer.startswith("]"):
                return

            if not buffer:
                if fim_arquivo:
                    return
                continue

            try:
                item, indice = decoder.raw_decode(buffer)
            except json.JSONDecodeError:
                if fim_arquivo:
                    raise
                trecho = arquivo.read(chunk_size)
                if trecho:
                    buffer += trecho
                else:
                    fim_arquivo = True
                continue

            buffer = buffer[indice:]
            yield item
