def extrair_percentual(bucket):
    """
    Recupera o percentual de um bucket da wallet.
    """
    if not isinstance(bucket, dict):
        return 0.0

    percentual = bucket.get("percent")

    if percentual is None:
        percentual = bucket.get("percentDetail")

    if percentual is None:
        return 0.0

    try:
        return float(percentual)
    except (TypeError, ValueError):
        return 0.0
</pre> BUCKETS = {     "stocks": "pct_stocks",     "fixedIncome": "pct_fixed_income",     "repo": "pct_repo",     "investimentFund": "pct_investment_fund",     "balance": "pct_cash",     "options": "pct_options",     "treasure": "pct_treasure",     "future": "pct_future",     "privatePension": "pct_private_pension",     "term": "pct_term",     "coe": "pct_coe",     "realEstate": "pct_real_estate",     "structruedProduct": "pct_structured_product", }   def extrair_percentual(bucket):     """     Recupera o percentual de um bucket da wallet.     """     if not isinstance(bucket, dict):         return 0.0      percentual = bucket.get("percent")      if percentual is None:         percentual = bucket.get("percentDetail")      if percentual is None:         return 0.0      try:         return float(percentual)     except (TypeError, ValueError):         return 0.0 In [7]: Copied! <pre>def carregar_wallet(path):
    linhas = []

    for item in stream_json_array(path):
        client = item.get("client")
        response = item.get("response") or {}

        sucesso = bool(
            response.get("success", False)
        )

        output = response.get("output") or {}

        linha = {
            "accountCode": str(client),
            "wallet_ok": sucesso,
            "wallet_updated_at": output.get("updatedAt"),
        }

        percentuais = []

        for bucket_original, feature in BUCKETS.items():
            if sucesso:
                percentual = extrair_percentual(
                    output.get(bucket_original)
                )
            else:
                percentual = np.nan

            linha[feature] = percentual
            percentuais.append(percentual)

        if sucesso:
            linha["num_active_buckets"] = int(
                sum(p &gt; 0 for p in percentuais)
            )
            linha["max_bucket_pct"] = max(percentuais)
            linha["pct_sum_selected"] = sum(percentuais)
            linha["empty_wallet"] = bool(
                all(p == 0 for p in percentuais)
            )
        else:
            linha["num_active_buckets"] = np.nan
            linha["max_bucket_pct"] = np.nan
            linha["pct_sum_selected"] = np.nan
            linha["empty_wallet"] = False

        linhas.append(linha)

    return pd.DataFrame(linhas)
