    embedding = (
        reducer.fit_transform(
            X_sample
        )
    )

    umap_results[
        n_neighbors
    ] = embedding

    plot_df = pd.DataFrame({
        "dim1":
            embedding[:, 0],
        "dim2":
            embedding[:, 1],
        "perfil":
            y_sample,
    })

    sns.scatterplot(
        data=plot_df,
        x="dim1",
        y="dim2",
        hue="perfil",
        alpha=0.55,
        s=24,
        ax=ax,
        legend=(
            ax is axes[0]
        ),
    )

    ax.set_title(
        f"n_neighbors = {n_neighbors}"
    )

    ax.set_xlabel(
        "Dimensão 1"
    )

    ax.set_ylabel(
        "Dimensão 2"
    )

fig.suptitle(
    "Figura 12 — UMAP do conjunto de treino",
    y=1.03,
)

plt.tight_layout()
plt.show()

print(
    "Conclusão: serão consideradas principalmente estruturas "
    "que persistam quando n_neighbors é alterado. "
    "A interpretação final deve ser escrita após observar a figura."
)
